CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY, owner_id text NOT NULL, agency text NOT NULL, filename text NOT NULL, storage_key text NOT NULL UNIQUE, mime_type text NOT NULL, size_bytes bigint NOT NULL CHECK(size_bytes > 0), sha256 text NOT NULL, status text NOT NULL CHECK(status IN ('queued','processing','needs_review','approved','failed','submitted')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_documents_sha_owner ON documents(owner_id, sha256);
CREATE TABLE IF NOT EXISTS invoice_extractions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE, provider text NOT NULL, payload jsonb NOT NULL, confidence numeric(5,4), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS approval_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), document_id uuid NOT NULL REFERENCES documents(id), actor_id text NOT NULL, decision text NOT NULL CHECK(decision IN ('approved','rejected','corrected')), correction jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS erp_sync (document_id uuid PRIMARY KEY REFERENCES documents(id), idempotency_key text NOT NULL UNIQUE, erp_id text, status text NOT NULL, attempts integer NOT NULL DEFAULT 0, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id text NOT NULL, title text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('user','assistant')), content text NOT NULL, sources jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, actor_id text NOT NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS ix_audit_resource ON audit_logs(resource_type, resource_id, created_at DESC);
